/**
 * Callouts are overlays that display onboarding or coaching content.
 *
 * - {@link https://livingdesign.walmart.com/components/callout/ Guidelines}
 * - {@link https://livingdesign.walmart.com/components/callout/react/ React documentation}
 *
 * The Callout component must be configured as follows to meet accessibility requirements:
 *
 * 1. Must provide a single, button-like target element as its children
 * 1. Must provide a description of the target element in `a11yContentLabel`
 * 1. Must provide the target element's ref as its `targetRef`
 *
 * ```tsx
 * import * as React from "react";
 * import {Button, Callout} from "@walmart-web/livingdesign-components";
 *
 * export default () => {
 *   const [isOpen, setIsOpen] = React.useState(false);
 *   const ref = React.useRef();
 *
 *     return (
 *       <Callout
 *         a11yContentLabel="Target information"
 *         content="Example Callout content."
 *         isOpen={isOpen}
 *         onClose={(event) => {
 *           setIsOpen(false);
 *         }}
 *        targetRef={ref}
 *       >
 *         <Button
 *           onClick={(event) => {
 *           setIsOpen((state) => !state);
 *           }}
 *           ref={ref}
 *           variant="primary"
 *         >
 *           Target
 *         </Button>
 *       </Callout>
 *     );
 *   };
 *```
 *
 * ### Position
 *
 * The Callout has eight positions. They are `bottomCenter` (default), `bottomLeft`, `bottomRight`, `left`, `right`, `topCenter`, `topLeft`, or `topRight`. The position can be set through the `position` prop.
 *
 * ```tsx
 *   <Callout
 *      position="topRight"
 *      {...}
 *    >
 *      {...}
 *      </Button>
 *    </Callout>
 * ```
 */
export declare const Callout: React.FunctionComponent<CalloutProps>;
